    fun checkRecordMesgTimestampsAgainstSessionMesgTimes(
        sessionMesgs: List<SessionMesg>,
        recordMesgs: List<RecordMesg>
    ): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "Record Message Timestamps Fall Within Session Message Times",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (sessionMesgs.isEmpty() || recordMesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        val firstSessionMesgStartTime = sessionMesgs[0].startTime
        val lastSessionMesgEndTime = calculateEndTime(sessionMesgs[sessionMesgs.size - 1])

        if ((firstSessionMesgStartTime == null) || (lastSessionMesgEndTime == null)) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "One or more Session Messages contain a null Start Time and/or a null 'End Time'."
            return result
        }

        val firstRecordMesgTimestamp = recordMesgs[0].timestamp
        val lastRecordMesgTimestamp = recordMesgs[recordMesgs.size - 1].timestamp

        if ((firstRecordMesgTimestamp == null) || (lastRecordMesgTimestamp == null)) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description = "One or more Record messages contain a null Timestamp."
            return result
        }

        if (firstRecordMesgTimestamp.timestamp - firstSessionMesgStartTime.timestamp < -1) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "One or more Record message Timestamps is earlier than Session Start Time."
            return result
        }

        if (lastRecordMesgTimestamp.timestamp - lastSessionMesgEndTime > 1) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "One or more Record message Timestamps is later than Session 'End Time'."
            return result
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun checkRecordMesgsAreChronological(recordMesgs: List<RecordMesg>): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "Record Messages Are in Chronological Ascending Order",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (recordMesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        val hasNullTimestamp = recordMesgs.any { it.timestamp == null }

        if (hasNullTimestamp) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description = "One or more Record messages contain a null Timestamp."
            return result
        }

        var previousTimestamp = recordMesgs[0].timestamp

        for (recordMesg in recordMesgs) {
            if (previousTimestamp!!.after(recordMesg.timestamp!!)) {
                result.status = ActivityFileValidationResult.Status.FAILED
                result.description = "One or more Record messages are not sequential."
                return result
            }
            previousTimestamp = recordMesg.timestamp
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun checkDeviceInfoMesgValidTimestamp(deviceInfoMesgs: List<DeviceInfoMesg>): ActivityFileValidationResult {
        return checkMesgValidTimestamp(deviceInfoMesgs, "Device Info")
    }

    fun checkDeviceInfoMesgValidDeviceIndex(deviceInfoMesgs: List<DeviceInfoMesg>): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "Device Info Message Device Index is Valid",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (deviceInfoMesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        val hasNullDeviceIndex = deviceInfoMesgs.any { it.deviceIndex == null }

        if (hasNullDeviceIndex) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "One or more Device Info messages contain a null Device Index value."
            return result
        }

        val hasCreator = deviceInfoMesgs.any { it.deviceIndex == DeviceIndex.CREATOR }

        if (!hasCreator) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "At least one Device Info message Device Index field needs to be set to Creator."
            return result
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun checkDeviceInfoMesgValidManufacturerIdExists(deviceInfoMesgs: List<DeviceInfoMesg>): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "Device Info Message Manufacturer Id is Valid",
            ActivityFileValidationResult.Level.OPTIONAL
        )

        if (deviceInfoMesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        val hasNullManufacturer = deviceInfoMesgs.any { it.manufacturer == null }

        if (hasNullManufacturer) {
            result.status = ActivityFileValidationResult.Status.WARNING
            result.description = "One or more Device Info messages contain a null Manufacturer Id."
            return result
        }

        val hasInvalidManufacturer = deviceInfoMesgs.any {
            Manufacturer.getStringFromValue(it.manufacturer ?: Manufacturer.INVALID) == ""
        }

        if (hasInvalidManufacturer) {
            result.status = ActivityFileValidationResult.Status.WARNING
            result.description =
                "One or more Device Info messages contain an unknown Manufacturer Id."
            return result
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    @SafeVarargs
    fun isEmpty(vararg lists: List<Mesg>) = lists.any { it.isEmpty() }

    fun checkValidMesgIndexes(mesgs: List<Mesg>, mesgName: String): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "$mesgName Message Valid Message Index",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (mesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        for (i in mesgs.indices) {
            val messageIndex =
                mesgs[i].getFieldIntegerValue(254, 0, Fit.SUBFIELD_INDEX_MAIN_FIELD)

            if (messageIndex == null) {
                result.status = ActivityFileValidationResult.Status.FAILED
                result.description =
                    "One or more $mesgName messages contain a null Message Index value."
                return result
            }

            if (messageIndex != i) {
                result.status = ActivityFileValidationResult.Status.FAILED
                result.description = "Message Indexes are not sequential."
                return result
            }
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun checkMesgValidTimestamp(mesgs: List<Mesg>, name: String): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "$name Message Timestamps are Valid",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (mesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        val hasNullTimestamp = mesgs.any { it.getFieldLongValue("timestamp") == null }

        if (hasNullTimestamp) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description = "One or more $name messages contain a null Timestamp."
            return result
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun checkValidFieldSums(
        mesg: Mesg,
        mesgs: List<Mesg>,
        mesgName: String,
        mesgListName: String,
        fieldName: String
    ): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "$mesgName Message $fieldName is Equal to the Sum of $mesgListName Messages $fieldName Values",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (mesgs.isEmpty()) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            return result
        }

        if ((mesg.getFieldFloatValue(fieldName) == null)) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description = "$mesgName Message contains a null $fieldName"
            return result
        }

        val hasNullValue = mesgs.any { it.getFieldFloatValue(fieldName) == null }
        if (hasNullValue) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description = mesgListName + "Message contains a null " + fieldName + " value."
            return result
        }

        val sumOfFieldValues = mesgs.sumOf { it.getFieldFloatValue(fieldName)!!.toDouble() }
        if (abs(mesg.getFieldFloatValue(fieldName)!! - sumOfFieldValues) > 1) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "$mesgName message $fieldName does not equal the sum of $mesgListName messages $fieldName values."
            return result
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun checkMesgsAreSequentialAndAbut(
        mesgs: List<Mesg>,
        mesgName: String
    ): ActivityFileValidationResult {
        val result = ActivityFileValidationResult(
            "$mesgName Message Are Sequential and Abut",
            ActivityFileValidationResult.Level.REQUIRED
        )

        if (mesgs.size <= 1) {
            result.status = ActivityFileValidationResult.Status.SKIPPED
            result.description =
                "Check requires two or more " + mesgName + " messages, found " + mesgs.size + "."
            return result
        }

        val hasNullStartTime = mesgs.any { it.getFieldLongValue("start_time") == null }
        val hasNullTotalElapsedTime =
            mesgs.any { it.getFieldLongValue("total_elapsed_time") == null }

        if (hasNullStartTime || hasNullTotalElapsedTime) {
            result.status = ActivityFileValidationResult.Status.FAILED
            result.description =
                "One or more $mesgName messages contain a null Start Time and/or a null Total Elapsed Time."
            return result
        }

        var previousEndTime = calculateEndTime(mesgs[0])!!

        for (mesg in mesgs.subList(1, mesgs.size)) {
            val startTime = mesg.getFieldLongValue("start_time")

            if (abs(startTime!! - previousEndTime) > 2) {
                result.status = ActivityFileValidationResult.Status.FAILED
                result.description = "$mesgName messages are not sequential, or do not abut."
                return result
            }

            previousEndTime = calculateEndTime(mesg)!!
        }

        result.status = ActivityFileValidationResult.Status.PASSED

        return result
    }

    fun anyMatchNull(mesgs: List<Mesg>, fieldName: String) =
        mesgs.any { it.getFieldValue(fieldName) == null }

    fun allMatchNull(mesgs: List<Mesg>, fieldName: String) =
        mesgs.any { it.getFieldValue(fieldName) == null }


    fun checkFieldValuesAreValid(
        mesgs: List<Mesg>,
        fieldName: String
    ): ActivityFileValidationResult.Status {
        if (mesgs.isEmpty()) {
            return ActivityFileValidationResult.Status.SKIPPED
        }

        return if (anyMatchNull(mesgs, fieldName))
            ActivityFileValidationResult.Status.FAILED else ActivityFileValidationResult.Status.PASSED
    }

    fun checkSportValuesAreValid(mesgs: List<Mesg>): ActivityFileValidationResult.Status {
        val status = checkFieldValuesAreValid(mesgs, "sport")
        return if (status == ActivityFileValidationResult.Status.FAILED) ActivityFileValidationResult.Status.WARNING else status
    }

    fun checkSubSportValuesAreValid(mesgs: List<Mesg>): ActivityFileValidationResult.Status {
        val status = checkFieldValuesAreValid(mesgs, "sub_sport")
        return if (status == ActivityFileValidationResult.Status.FAILED) ActivityFileValidationResult.Status.WARNING else status
    }

    fun calculateEndTime(mesg: Mesg): Long? {
        try {
            val startTime = mesg.getFieldLongValue("start_time")!!
            val totalElapsedTime = mesg.getFieldLongValue("total_elapsed_time")!!
            return startTime + totalElapsedTime
        } catch (e: NullPointerException) {
            return null
        }
    }

    companion object {
        private const val MIN_TIMEZONE_OFFSET_IN_SECONDS = -43200 // -12 hours
        private const val MAX_TIMEZONE_OFFSET_IN_SECONDS = 50400 // +14 hours
    }
}